import torch
import torch.nn as nn

class DifferentiableSymbolicParser(nn.Module):
    def __init__(self, temperature: float = 1.0):
        super().__init__()
        self.temp = temperature

    def smooth_min(self, x: torch.Tensor, y: torch.Tensor) -> torch.Tensor:
        # Smooth Log-Sum-Exp (LSE) semiring addition operator:
        #   -temp * log( exp(-x/temp) + exp(-y/temp) )
        # Differentiable surrogate for the hard minimum: as temp -> 0+ it
        # approaches torch.minimum while gradients keep flowing to x and y.
        t = torch.as_tensor(self.temp, dtype=x.dtype, device=x.device)
        return -t * torch.log(torch.exp(-x / t) + torch.exp(-y / t))

